resource "aws_cognito_identity_pool" "ES_Cognito_Identity_Pool" {
  identity_pool_name               = "${var.ES_Cognito_Identity_Pool_Name}"
  allow_unauthenticated_identities = true # MUST BE TRUE FOR KIBANA TO USE THIS
  lifecycle {
    ignore_changes                 = ["*"]
  }
}

resource "aws_waf_web_acl" "AWS_Security_Blog_Blacklist_WACL" {
  name        = "${var.AWS_Security_Blog_Blacklist_WACL_Name}"
  metric_name = "${var.AWS_Security_Blog_Blacklist_WACL_Name}"
  default_action {
    type = "ALLOW"
  }
  rules {
    action {
      type = "BLOCK"
    }
    priority = 1
    rule_id  = "${aws_waf_rule.AWS_Security_Blog_SQL_Injection_Rule.id}"
    type     = "REGULAR"
  }
  rules {
    action {
      type = "BLOCK"
    }
    priority = 2
    rule_id  = "${aws_waf_rule.AWS_Security_Blog_IP_Blacklist_Rule.id}"
    type     = "REGULAR"
  }

